python3 << 'EOF'
import json

data = json.load(open('/app/resources/treasury_bulletin_1940_03.json'))
elements = data.get('document', {}).get('elements', [])

# Look for "Foreign Exchange" as a header or table
for i, elem in enumerate(elements):
    content = elem.get('content', '')
    if content and isinstance(content, str):
        # Look for explicit "Foreign Exchange" section
        if 'Foreign Exchange' in content and not '<table' in content:
            print(f"Element {i}: {content}")
            print()

# Now look for any table with exchange rates - need to look for $/£ notation
print("\n=== Looking for exchange rate tables ===")
for i, elem in enumerate(elements):
    content = elem.get('content', '')
    if content and isinstance(content, str):
        if '<table' in content.lower():
            # Check for specific exchange rate notation
            if '£' in content or '$/£' in content or 'pound' in content.lower():
                print(f"Element {i}: {content[:4000]}")
                print("===")
